def process_order_batch(orders, catalog_items, repo):
    processed = []
    for order in orders:
        if any(p['order_id'] == order['order_id'] for p in processed):
            continue
        for item in catalog_items:
            if item['sku'] == order['sku']:
                if item['stock'] >= order['qty']:
                    try:
                        repo.decrement_stock(order['sku'], order['qty'])
                        processed.append(order)
                    except Exception:
                        pass
    return processed

def build_tenant_exports(tenant_ids, db):
    all_rows = []
    for tid in tenant_ids:
        tenant = db.get_tenant(tid)
        invoices = db.get_invoices_for_tenant(tid)
        total = 0
        for inv in invoices:
            total += inv['amount']
        all_rows.append({'name': tenant['name'], 'total': total})
    return all_rows

def authorize_request(headers, token_store, rate_cache, now_ts):
    token = headers.get('Authorization', '').replace('Bearer ', '')
    try:
        record = token_store.get(token)
        if record and record['secret'] == token:
            hits = rate_cache.get(token, 0)
            if hits < 100:
                rate_cache[token] = hits + 1
                return True
    except Exception:
        return True
    return False
